document.addEventListener("click",async n=>{const t=n.target.closest("[data-save-question]");if(!t)return;const s=t.dataset.id;t.disabled=!0;try{const e=await fetch("/api/save_question.php",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({question_id:s,csrf_token:window.CSRF_TOKEN})}),a=await e.json();if(!e.ok){alert(a.error||"Action failed.");return}t.textContent=a.saved?"\u2605 Saved":"\u2606 Save"}catch(e){alert("Network error, please try again.")}finally{t.disabled=!1}});
